# How We Work
$managedProcess = @('Understand','Set up','Transition','Deliver','Review')
$teamFactors = @('Work type','Expected volumes','Required legal or business knowledge','Turnaround requirements','Client working hours','Production and review responsibilities','Quality-control requirements','Reporting and escalation needs','Project duration','Required systems and access')
