$howMain = @"
<section class="page-hero editorial-hero"><div class="container narrow"><p class="eyebrow">How we work</p><h1>Delivery starts with understanding the work</h1><p class="lead">Axentra reviews the work, people, systems, deadlines and expected output before proposing the team and delivery plan.</p><p>Where useful for the project, design-thinking methods help uncover user needs, dependencies and friction before solutions are proposed. Client feedback continues after work begins, so instructions, training and delivery can be adjusted throughout the engagement.</p><a class="button primary" href="$BasePath/contact.html">Discuss Your Requirement</a></div></section>
<section class="section process-section"><div class="container"><div class="section-heading split-heading"><div><p class="eyebrow">Company-wide process</p><h2>Five steps from discussion to ongoing review</h2></div><p>The same core process applies across projects, recurring workflows, dedicated teams and secondments.</p></div>$(Get-ProcessMarkup -Items $managedProcess -Label 'Axentra delivery process')</div></section>
<section class="section section-muted"><div class="container"><div class="delivery-stage-grid"><article><p class="section-index">01</p><h3>Understand</h3><p>Review the work, volumes, systems, deadlines, data and expected output.</p></article><article><p class="section-index">02</p><h3>Set up</h3><p>Agree the team, roles, instructions, access, quality checks, reporting and escalation routes.</p></article><article><p class="section-index">03</p><h3>Transition</h3><p>Complete knowledge transfer, training, system access, sample work and initial quality review.</p></article><article><p class="section-index">04</p><h3>Deliver</h3><p>Perform and review the work, track open items and report status under the agreed service structure.</p></article><article><p class="section-index">05</p><h3>Review</h3><p>Use quality findings, client feedback and recurring issues to improve instructions, training and delivery.</p></article></div></div></section>
