$(Get-ContactBand -Heading 'Discuss the work, team and coverage you need' -Copy 'Share the work type, volumes, systems, working hours, duration and review responsibilities.')
"@

Write-SiteFile -Path 'how-we-work.html' -Content (Get-Page -Title 'How We Work | Axentra' -Description 'See how Axentra understands, sets up, transitions, delivers and reviews legal and business process support with teams arranged around each engagement.' -Canonical "$SiteUrl/how-we-work.html" -Active 'work' -Main $howMain -BodyClass 'how-page')

# Security and Trust
